public String funnyString(String s) {
    String r = new StringBuilder(s).reverse().toString();
    int n = s.length();
    for (int i = 1; i < n; i++) {
        int ds = Math.abs(s.charAt(i) - s.charAt(i - 1));
        int dr = Math.abs(r.charAt(i) - r.charAt(i - 1));
        if (ds != dr) {
            return "Not Funny";
        }
    }
    return "Funny";
}

