public String funnyString(String s) {
    int n = s.length();
    for (int i = 1; i < n; i++) {
        int forward = Math.abs(s.charAt(i) - s.charAt(i - 1));
        int mirror = Math.abs(s.charAt(n - i) - s.charAt(n - i - 1));
        if (forward != mirror) {
            return "Not Funny";
        }
    }
    return "Funny";
}

